import React, { useState, useEffect } from "react";
import { useStatus } from "../contexts/StatusContext";
import { useI18n } from "../contexts/I18nContext";
import {
  UsersIcon,
  TasksIcon,
  ClockIcon,
  CpuIcon,
  ArrowUpIcon,
  ArrowDownIcon,
  ErrorIcon,
} from "./Icons";


interface StatCardProps {
  title: string;
  value: string | number;
  change?: string;
  changeType?: "increase" | "decrease" | "neutral";
  icon: React.ReactNode;
  color: "primary" | "success" | "warning" | "error" | "secondary";
}

const StatCard: React.FC<StatCardProps> = ({
  title,
  value,
  change,
  changeType = "neutral",
  icon,
  color,
}) => {
  const colorClasses = {
    primary: "gradient-primary",
    success: "gradient-success",
    warning: "gradient-warning",
    error: "gradient-error",
    secondary: "gradient-secondary",
  };

  const changeColorClasses = {
    increase: "text-success-600 bg-success-50",
    decrease: "text-error-600 bg-error-50",
    neutral: "text-secondary-600 bg-secondary-50",
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-6 card-hover">
      <div className="flex items-center">
        <div className={`p-3 rounded-lg ${colorClasses[color]} text-white`}>
          {icon}
        </div>
        <div className="ml-4 flex-1">
          <p className="text-sm font-medium text-secondary-600 mb-1">{title}</p>
          <p className="text-2xl font-bold text-secondary-900">{value}</p>
          {change && (
            <div
              className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium mt-2 ${changeColorClasses[changeType]}`}
            >
              {changeType === "increase" && (
                <ArrowUpIcon size="sm" className="mr-1" />
              )}
              {changeType === "decrease" && (
                <ArrowDownIcon size="sm" className="mr-1" />
              )}
              {change}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

interface ProgressBarProps {
  label: string;
  value: number;
  max: number;
  color: "primary" | "success" | "warning" | "error";
}

const ProgressBar: React.FC<ProgressBarProps> = ({
  label,
  value,
  max,
  color,
}) => {
  const percentage = Math.min((value / max) * 100, 100);

  const colorClasses = {
    primary: "bg-primary-500",
    success: "bg-success-500",
    warning: "bg-warning-500",
    error: "bg-error-500",
  };

  return (
    <div className="mb-4">
      <div className="flex justify-between text-sm text-secondary-600 mb-1">
        <span>{label}</span>
        <span>
          {value}/{max}
        </span>
      </div>
      <div className="w-full bg-secondary-200 rounded-full h-2">
        <div
          className={`h-2 rounded-full transition-all duration-300 ${colorClasses[color]}`}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
};

interface ClientStatusProps {
  clients: any[];
}

const ClientStatus: React.FC<ClientStatusProps> = ({ clients }) => {
  const { t } = useI18n();
  const statusCounts = clients.reduce((acc, client) => {
    const status = client.connection_status || "disconnected";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});

  const statusItems = [
    {
      status: "connected",
      label: t("common.online"),
      color: "success",
      count: statusCounts.connected || 0,
    },
    {
      status: "disconnected",
      label: t("common.offline"),
      color: "error",
      count: statusCounts.disconnected || 0,
    },
    {
      status: "connecting",
      label: t("header.connectionStatus"),
      color: "warning",
      count: statusCounts.connecting || 0,
    },
    {
      status: "error",
      label: t("common.error"),
      color: "error",
      count: statusCounts.error || 0,
    },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-4">
        {t("clients.connectionStatus")}
      </h3>
      <div className="space-y-3">
        {statusItems.map(
          (item) =>
            item.count > 0 && (
              <div
                key={item.status}
                className="flex items-center justify-between"
              >
                <div className="flex items-center">
                  <div
                    className={`w-3 h-3 rounded-full mr-3 ${
                      item.color === "success"
                        ? "status-online"
                        : item.color === "warning"
                          ? "status-warning"
                          : "status-offline"
                    }`}
                  />
                  <span className="text-sm text-secondary-600">
                    {item.label}
                  </span>
                </div>
                <span className="text-sm font-medium text-secondary-900">
